public class DeckTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Deck deck = new Deck();
        check("size of a fresh deck", 52, deck.size());
        check("first card dealt", "1 of clubs", String.valueOf(deck.deal()));
        check("second card dealt", "2 of clubs", String.valueOf(deck.deal()));
        check("size after two deals", 50, deck.size());
        check("contains(1, clubs) after it was dealt", false, deck.contains(1, "clubs"));
        check("contains(13, spades)", true, deck.contains(13, "spades"));
        check("contains(14, clubs) never exists", false, deck.contains(14, "clubs"));
        Card last = null;
        for (int i = 0; i < 60 && deck.size() > 0; i++) {
            last = deck.deal();
        }
        check("last card dealt", "13 of spades", String.valueOf(last));
        check("size after dealing everything", 0, deck.size());
        check("deal() on an empty deck", null, deck.deal());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

